;user-select:none;font-family:serif;transition:color .3s ease,transform .3s ease,filter .3s ease;z-index:1}.board-module:hover .module-watermark{color:#ff69b43d;filter:drop-shadow(0 0 8px rgba(255,20,147,.4));transform:scale(1.12) rotate(-6deg)}.module-corner-stud{position:absolute;width:4px;height:4px;pointer-events:none;z-index:3}.module-corner-stud.mcs-tr{top:4px;right:4px;border-top:1px solid rgba(255,105,180,.5);border-right:1px solid rgba(255,105,180,.5)}.module-corner-stud.mcs-bl{bottom:4px;left:9px;border-bottom:1px solid rgba(255,105,180,.5);border-left:1px solid rgba(255,105,180,.5)}.board-module:hover .module-corner-stud{border-color:#ffb6c1e6;box-shadow:0 0 4px #ff149399}.board-module.full-width{grid-column:1 / -1}.reward-pill-container{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.reward-pill{position:relative;display:inline-flex;align-items:center;justify-content:center;padding:6px 14px;border-radius:12px 3px;cursor:pointer;user-select:none;transition:all .3s cubic-bezier(.2,.8,.25,1);background:#18031ce6;border:1.5px solid rgba(255,64,129,.45);box-shadow:0 0 12px #ba186b59;overflow:hidden;min-height:32px}.reward-pill:hover{border-color:#ff69b4d9;box-shadow:0 0 18px #ff14938c;transform:translateY(-1px)}.reward-text{color:#ffcc80;font-weight:700;font-size:13px;letter-spacing:.5px;text-shadow:0 0 8px rgba(255,152,0,.7);transition:filter .3s ease,opacity .3s ease;white-space:nowrap}.reward-succubus-seal{position:absolute;inset:0;border-radius:10px 2px;background:linear-gradient(135deg,#6b21a8,#c026d3 45%,#e11d48);background-size:200% 200%;animation:succubusSealShimmer 3.2s infinite ease-in-out;border:1px solid rgba(255,182,193,.85);box-shadow:0 0 14px #ec4899bf,inset 0 0 8px #ffffff59;display:flex;align-items:center;justify-content:center;gap:4px;padding:0 8px;pointer-events:none;z-index:2;transition:transform .25s ease,opacity .25s ease}@keyframes succubusSealShimmer{0%,to{opacity:.9}50%{opacity:1}}.seal-heart{font-size:16px;line-height:1;color